AngleRestriction         structure/layer.rs
FixedState               structure/mod.rs
Unit                     structure/mod.rs
Unit                     structure/layer.rs
BoardOutline             structure/board_outline.rs
BoardOutline             items/*.rs
Component                structure/component.rs
Components               structure/component.rs
Layer                    structure/layer.rs
LayerStructure           structure/layer.rs
ShapeAndEntrySide        structure/shape_entry_side.rs
ShapeEntrySide           structure/shape_entry_side.rs

# --- board/facade ------------------------------------------------------------------------------
# All eight classes of `board/facade` make up one Rust `Board` (plan-2 ruling 1), so all eight map
# to the same glob — nine rows in this file use it, the ninth being `Item` above, whose own methods
# are answered partly by `Board`. `board/*.rs` is `mod.rs`, `query.rs`,
# `normalize.rs`, `snapshot.rs`, `connectivity.rs`, `clearance.rs`, `changed_area.rs`,
# `communication.rs`, `shape_trace_entries.rs` and `trace_normalize.rs`.
BasicBoard               board/*.rs
BoardItemRepository      board/*.rs
BoardConnectivityQueries board/*.rs
BoardSnapshotManager     board/*.rs
RoutingBoard             board/*.rs
RoutingBoardOperations   board/*.rs
RoutingBoardSearchFacade board/*.rs
RoutingBoardUndoFacade   board/*.rs

